"use client"

import { useMemo, useState } from 'react'
import type { ProductDetail } from '@/lib/data/product-detail'
import { formatPrice } from '@/lib/data/product-detail'
import { ProductModal } from './product-modal'
import s from './product-purchase-panel.module.css'

interface ProductPurchasePanelProps {
	product: ProductDetail
}

export function ProductPurchasePanel({ product }: ProductPurchasePanelProps) {
	const [selectedSize, setSelectedSize] = useState<string>()

	const priceLabel = useMemo(() => formatPrice(product.price, product.currency), [product.price, product.currency])

	return (
		<div className={s.panel}>
			<div>
				<p className={s.kicker}>{product.kicker}</p>
				<h1 className={s.title}>{product.name}</h1>
				<p className={s.price}>
					{priceLabel} · <span>{product.colorway}</span>
				</p>
			</div>

			<p className={s.description}>{product.description}</p>

			<ul className={s.highlights}>
				{product.highlights.map((item) => (
					<li key={item}>{item}</li>
				))}
			</ul>

			<div>
				<p className={s.kicker}>Select size</p>
				<div className={s.sizeGrid}>
					{product.sizeOptions.map((size) => (
						<button
							key={size}
							type='button'
							className={`${s.sizeButton} ${selectedSize === size ? s.sizeButtonActive : ''}`}
							onClick={() => setSelectedSize(size)}
						>
							EU {size}
						</button>
					))}
				</div>
			</div>

			<div className={s.fitRow}>
				<div className={s.kicker}>
					{product.fit.label}: {product.fit.description}
				</div>
				<div className={s.fitBar}>
					<span
						className={s.fitIndicator}
						style={{ left: `${product.fit.value}%` }}
						aria-label={product.fit.description}
					/>
				</div>
			</div>

			<div className={s.actions}>
				<button className={s.primaryButton} type='button'>
					{selectedSize ? `Add EU ${selectedSize} to bag` : 'Add to bag'}
				</button>
				<div className={s.modalRow}>
					<ProductModal title='Materials & Details' triggerLabel='Details'>
						<ul>
							{product.materials.map((material) => (
								<li key={material}>{material}</li>
							))}
						</ul>
					</ProductModal>
					<ProductModal title='Care Guide' triggerLabel='Care'>
						<ul>
							{product.careNotes.map((note) => (
								<li key={note}>{note}</li>
							))}
						</ul>
					</ProductModal>
					<ProductModal title='Shipping & Returns' triggerLabel='Shipping'>
						<ul>
							{product.shippingNotes.map((note) => (
								<li key={note}>{note}</li>
							))}
						</ul>
					</ProductModal>
				</div>
			</div>
		</div>
	)
}
