"use client"

import { useState } from 'react'
import 'keen-slider/keen-slider.min.css'
import { useKeenSlider } from 'keen-slider/react'
import { Image } from '@/components/image'
import type { ProductGalleryImage } from '@/lib/data/product-detail'
import s from './product-gallery.module.css'

interface ProductGalleryProps {
	images: ProductGalleryImage[]
}

export function ProductGallery({ images }: ProductGalleryProps) {
	const [currentSlide, setCurrentSlide] = useState(0)
	const [sliderRef, instanceRef] = useKeenSlider<HTMLDivElement>(
		{
			loop: true,
			dragSpeed: 0.8,
			initial: 0,
			slideChanged(slider) {
				setCurrentSlide(slider.track.details.rel)
			},
		},
		[],
	)

	const moveTo = (idx: number) => {
		instanceRef.current?.moveToIdx(idx)
	}

	return (
		<div className={s.gallery}>
			<div ref={sliderRef} className={`keen-slider ${s.slider}`}>
				{images.map((image, index) => (
					<div key={image.id} className={`keen-slider__slide ${s.slide}`}>
						<Image
							src={image.src}
							alt={image.alt}
							width={image.width}
							height={image.height}
							className={s.slideImage}
							priority={index === 0}
							sizes="(max-width: 768px) 100vw, 70vw"
						/>
					</div>
				))}
			</div>

			<div className={s.thumbnails} aria-hidden="true">
				{images.map((image, index) => (
					<button
						key={`thumb-${image.id}`}
						type='button'
						className={s.thumbnailButton}
						onClick={() => moveTo(index)}
						aria-pressed={currentSlide === index}
					>
						<Image
							src={image.src}
							alt=''
							width={120}
							height={120}
							className={s.thumbnailImage}
						/>
					</button>
				))}
			</div>

			<div className={s.controls}>
				<button type='button' className={s.controlButton} onClick={() => instanceRef.current?.prev()} aria-label='Previous image'>
					←
				</button>
				<button type='button' className={s.controlButton} onClick={() => instanceRef.current?.next()} aria-label='Next image'>
					→
				</button>
			</div>

			<div className={s.dots}>
				{images.map((_, index) => (
					<span key={`dot-${index}`} className={`${s.dot} ${currentSlide === index ? s.dotActive : ''}`} />
				))}
			</div>
		</div>
	)
}
